const request = $('Profile Auth Webhook').first().json.body || {};
const row = $input.first()?.json || {};
const hasProfile = row.id !== undefined && row.id !== null;

if (request.action === 'list') {
  return [{ json: { status: 'success', profiles: $input.all().map(item => item.json) } }];
}

if (!hasProfile) {
  return [{ json: { status: 'error', message: request.action === 'login' ? 'Incorrect username or password' : 'Profile could not be created' } }];
}

return [{ json: { status: 'success', profile: row } }];
